use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

/// Upper bound on `lookup` calls per run, so a model that keeps asking for
/// tools cannot loop this node indefinitely.
const MAX_TOOL_ROUNDS: usize = 4;

/// The only tool in this node's scope. Any other tool name the model requests
/// is refused, because the node holds no interface for it.
const LOOKUP_TOOL: &str = "lookup";

const SYSTEM: &str = "You answer customer-support questions. Use only the \
provided context. If you need more information, request the `lookup` tool \
with a short query; otherwise answer the question directly.";

struct Node;

fn intent_label(intent: &Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The `requires len(question) <= 512` precondition is the caller's
        // guarantee and is not re-checked here.

        let mut transcript = format!(
            "Intent: {}\nQuestion: {}\n\nKnowledge:\n",
            intent_label(&ctx.intent),
            ctx.question,
        );
        for fact in &ctx.knowledge {
            transcript.push_str("- ");
            transcript.push_str(fact);
            transcript.push('\n');
        }

        let mut reply = tool_llm::generate(SYSTEM, &transcript);
        let mut rounds: usize = 0;

        loop {
            match reply {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != LOOKUP_TOOL {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool `{}` is not in scope", req.tool),
                        });
                    }
                    if rounds == MAX_TOOL_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-call budget exhausted".to_string(),
                        });
                    }
                    rounds += 1;

                    let hits = kb_read::lookup(&req.query);
                    transcript.push_str(&format!(
                        "\nTool `lookup` for {:?} returned:\n",
                        req.query
                    ));
                    for hit in &hits {
                        transcript.push_str("- ");
                        transcript.push_str(hit);
                        transcript.push('\n');
                    }

                    reply = tool_llm::generate(SYSTEM, &transcript);
                }
            }
        }
    }
}

export!(Node);
